def main():
    contexts={d['attempt_id']:d for d in map(json.loads,(HERE/'evidence_context.jsonl').read_text(encoding='utf8').splitlines())}
    second_path=HERE/'second_review.jsonl'
    assert sha(second_path.read_bytes())=='df45928a843dfe445d469eac184ae1569bfd02047467fa482affbc803e3de7cf', 'Preserve frozen independent reviews'
    second={d['attempt_id']:d for d in map(json.loads,second_path.read_text(encoding='utf8').splitlines())}
    merged={'RS09':'RS10','RS13':'RS11'}; records=[]; inputs=[]; reviews=[]
    for aid,d in contexts.items():
        family=contexts[merged.get(aid,aid)]['family_id']; base={k:d[k] for k in ['attempt_id','occurrence_id','ref','stratum','source_file','source_sha256','version_title','json_index']}
        base.update({'family_id':family,'original_provisional_family_id':d['family_id'],'review_level':'ai_single','reader':'Codex scholar_audit agent; AI, not human','context_status':'focal question and listed continuation read; wider parallels not fully certified','reasoning_provenance':'Hebrew input is annotator paraphrase; explanations in notes are source-reading inferences, not source quotations','split_permission':'development_only; no confirmation scoring','grouping_status':'provisional; manual links included but cross-corpus parallel audit incomplete'})
        base.update({'review_level':'ai_independent_double','review_files':['initial_reviews_round1.jsonl','initial_reviews.jsonl','second_review.jsonl'],'independent_second_status':second[aid]['status'],'review_qualification':'Two independently initiated AI readings; no knowledgeable-human review; retained scope disagreements are not consensus.'})
        if aid in FAILURES:
            reason,note=FAILURES[aid]; base.update({'eligibility':'excluded_or_pending','reason':reason,'notes':note,'attribution':None,'prediction_view':None}); reviews.append({'attempt_id':aid,'initial_eligibility':'excluded_or_pending','initial_assignment':None,'reader':'ai_single'})
        else:
            q,c,r,s,kind,refs,status,note=READINGS[aid]; candidates=[{'candidate_id':sha(t.encode())[:16],'text_he':t} for t in [r,s]]; assignment={'Rav':candidates[0]['candidate_id'],'Shmuel':candidates[1]['candidate_id']}; candidates.sort(key=lambda x:x['candidate_id'])
            units={u['ref']:u for u in d['source_units']}; spans=[{'ref':ref,'text':units[ref]['text'],'raw_text':units[ref]['raw_text'],'json_index':units[ref]['json_index']} for ref in refs.split('|')]
            base.update({'eligibility':'provisional_usable','question_he':q,'conditions_he':c,'candidates':candidates,'attribution':assignment,'attribution_status':'direct_or_named_transmission_in_this_merged_version','discussion_status':status,'decision_type':kind,'evidence_spans':spans,'notes':note})
            inputs.append({'case_id':sha(aid.encode())[:16],'question_he':q,'conditions_he':c,'candidates':candidates})
            reviews.append({'attempt_id':aid,'initial_eligibility':'provisional_usable','initial_assignment':assignment,'reader':'ai_single'})
        records.append(base)
    lines('evidence_records.jsonl',records); lines('prediction_inputs.jsonl',inputs)
    # Initial reviews are immutable historical artifacts, not regenerated after adjudication.
    assert (HERE/'initial_reviews.jsonl').exists() and (HERE/'initial_reviews_round1.jsonl').exists()
    lines('attempted_families.jsonl',[{k:r[k] for k in ['attempt_id','occurrence_id','family_id','original_provisional_family_id','ref','stratum','eligibility']} for r in records])
    disagreements=[
      {'attempt_id':'RS10','first_initial':'excluded_or_pending','second_initial':'eligible_conditional','issue':'Transaction/version and interpretation scope','resolution':'pending_retained','reason':'Need explicit transaction schema; no forced consensus or categorical valid/invalid labels.'},
      {'attempt_id':'RS21','first_initial':'excluded_or_pending','second_initial':'eligible_interpretive','issue':'Alternative derivations of shared norm versus eligible interpretation','resolution':'excluded_under_current_scope','reason':'Retain both initial judgments. Distinct derivations remain available for later interpretive study, not opposing choices in this pilot.'},
      {'attempt_id':'RS32','first_round1':'excluded_or_pending','first_after_context_extension':'provisional_usable','second_initial':'eligible_conditional','issue':'Initially missing mishnah boundary','resolution':'usable_after_recorded_first_reader_extension','reason':'Eruvin 41b:6–8 resolved first-reader boundary before second comparison. This is not initial eligibility agreement.'},
      {'attempt_id':'RS14','first_initial':'provisional_usable','second_initial':'eligible_conditional','issue':'Neutral view lacked both-public-thoroughfare ends, closable door, and legal-rule/instruction distinction','resolution':'neutral_input_corrected_by_source_adjudication','evidence_refs':['Eruvin 6b:9','Eruvin 7a:4','Eruvin 7a:5','Eruvin 7a:12','Eruvin 7a:13','Eruvin 7a:15'],'reason':'Substantive attribution unchanged; candidate text hash changes because closability is now explicit.'}]
    lines('review_disagreements.jsonl',disagreements)
    dump('manual_family_links.json',[{'left':'RS09','right':'RS10','evidence':'Bava Batra 152b:6–8 explicitly refers back to 152a:1 and gives alternative transmission; same discussion family'},{'left':'RS11','right':'RS13','evidence':'Pesachim 101a:7–9 repeats Shabbat 22a:5–6 named assignments; answer-bearing context leakage despite different focal question'}])
    summary={'attempted_occurrences':len(records),'attempted_candidate_families_after_manual_merges':len(set(r['family_id'] for r in records)),'provisional_usable_focal_cases':len(inputs),'independent_human_reviewers':0,'independent_second_AI_reviews':32,'review_level':'ai_independent_double','agreement':{'original_30_initial_eligibility':{'agree':28,'denominator':30},'all_32_round1_eligibility':{'agree':29,'denominator':32},'all_32_after_first_reader_extension_eligibility':{'agree':30,'denominator':32},'original_30_jointly_named_assignment':{'agree':22,'denominator':22},'all_32_round1_jointly_named_assignment':{'agree':23,'denominator':23},'all_32_current_jointly_named_assignment':{'agree':24,'denominator':24},'assignment_method':'Independent reviewer semantic matching of separately authored paraphrases; missing labels excluded; descriptive conditional agreement, not accuracy.'},'failures':dict(collections.Counter(r.get('reason') for r in records if r['eligibility']!='provisional_usable')),'status':'PROVISIONAL_PENDING_REVIEW','source_families_certified_disjoint':False}
    dump('feasibility_summary.json',summary); print(json.dumps(summary,indent=2))
if __name__=='__main__': main()
